import { bootstrapExtra } from "@workadventure/scripting-api-extra";

WA.onInit().then(async () => {
  // Accueil : la mascotte dit simplement « Bienvenue » a l'arrivee, puis la bulle disparait.
  try {
    const w = await WA.room.website.get("bulle_accueil");
    w.url = new URL("bulle.html?dialogue=bureau&court=1&pointe=bas&t=" + Date.now(), WA.room.mapURL).toString();
    w.visible = true;
    setTimeout(() => { w.visible = false; }, 8000);   // filet de securite : la bulle se ferme d'elle-meme apres le message
  } catch (e) { console.error(e); }
  bootstrapExtra().catch(e => console.error(e));
}).catch(e => console.error(e));

export {};
